import React from 'react';
import { useParams } from 'react-router-dom';

// Basic ProcessPage component
const ProcessPage = () => {
  let { processId } = useParams();

  return (
    <div>
      <h2>Process Page (ID: {processId})</h2>
      <p>This page will have a split layout: Chat on the left, Process Details/Visualization on the right.</p>
      {/* ChatInterface and ProcessVisualization components will go here */}
    </div>
  );
};

export default ProcessPage;
